#!/usr/bin/env node
/**
 * 🔥 Yuji Itadori Contribution Animation Generator
 * Yuji charges cursed energy and fires a blast at each GitHub contribution
 * block, destroying them one by one.
 *
 * Usage:
 *   GITHUB_TOKEN=xxx GITHUB_USERNAME=you node generate.js
 */

const https = require('https');
const fs    = require('fs');

const TOKEN = process.env.GITHUB_TOKEN;
const USER  = process.env.GITHUB_USERNAME;

// ───────────────────────────────────────────────────────────
//  Real pixel-art Yuji sprite frames (base64 PNG, transparent bg)
//  12 frames: idle → charge x9 → release → recoil
//  Each frame: 96×114 px (NEAREST-scaled pixel art)
// ───────────────────────────────────────────────────────────
const SPRITE_FRAMES = [
  /* 00 */ "data:image/png;base64,",
  /* 01 */ "data:image/png;base64,",
  /* 02 */ "data:image/png;base64,",
  /* 03 */ "data:image/png;base64,",
  /* 04 */ "data:image/png;base64,",
  /* 05 */ "data:image/png;base64,",
  /* 06 */ "data:image/png;base64,",
  /* 07 */ "data:image/png;base64,",
  /* 08 */ "data:image/png;base64,",
  /* 09 */ "data:image/png;base64,",
  /* 10 */ "data:image/png;base64,",
  /* 11 */ "data:image/png;base64,",
];

// Fireball / cursed energy projectile sprite (75×32 px, transparent bg)
const FIREBALL_SPRITE = "data:image/png;base64,";

// Sprite frame index meanings:
//  0        = idle
//  1-9      = charging cursed energy (fireball grows in hand)
//  10       = release pose (fireball leaves hand) - held during flight
//  11       = recoil / recovery
const CHARGE_FRAMES = [1,2,3,4,5,6,7,8,9];
const RELEASE_FRAME = 10;
const RECOIL_FRAME  = 11;
const IDLE_FRAME     = 0;

// Hand / muzzle point, relative to sprite top-left (96x114 canvas)
const HAND_X = 88;
const HAND_Y = 47;

const FB_W = 75, FB_H = 32; // fireball sprite dimensions

// ─────────────────────────────────────────────────────────────
//  GitHub GraphQL — fetch contribution calendar
// ─────────────────────────────────────────────────────────────

async function fetchContributions(username) {
  const to   = new Date().toISOString();
  const from = new Date(Date.now() - 365 * 24 * 60 * 60 * 1000).toISOString();

  const query = `{
    user(login: "${username}") {
      contributionsCollection(from: "${from}", to: "${to}") {
        contributionCalendar {
          totalContributions
          weeks {
            contributionDays {
              contributionCount
              date
            }
          }
        }
      }
    }
  }`;

  return new Promise((resolve, reject) => {
    const payload = JSON.stringify({ query });
    const req = https.request(
      {
        hostname: 'api.github.com',
        path: '/graphql',
        method: 'POST',
        headers: {
          Authorization:   `Bearer ${TOKEN}`,
          'Content-Type':  'application/json',
          'Content-Length': Buffer.byteLength(payload),
          'User-Agent':    'yuji-contribution-anim/1.0',
        },
      },
      res => {
        let body = '';
        res.on('data', chunk => (body += chunk));
        res.on('end', () => {
          try {
            const { data, errors } = JSON.parse(body);
            if (errors) return reject(new Error(JSON.stringify(errors)));
            resolve(data.user.contributionsCollection.contributionCalendar);
          } catch (e) { reject(e); }
        });
      }
    );
    req.on('error', reject);
    req.write(payload);
    req.end();
  });
}

// ─────────────────────────────────────────────────────────────
//  Cell colours (GitHub palette)
// ─────────────────────────────────────────────────────────────

function cellColor(count) {
  if (count === 0) return '#161b22';
  if (count <= 2)  return '#0e4429';
  if (count <= 5)  return '#006d32';
  if (count <= 8)  return '#26a641';
  return '#39d353';
}

// ─────────────────────────────────────────────────────────────
//  SMIL helper — every keyTimes/values array built here is
//  guaranteed to start at 0 and end at 1, which the SVG/SMIL
//  spec requires for non-"paced" calcMode. Skipping this is
//  what silently breaks animations in real browsers.
// ─────────────────────────────────────────────────────────────

function closeAnim(keyTimesArr, valuesArr) {
  const kt = keyTimesArr.slice();
  const vs = valuesArr.slice();
  if (kt[0] !== 0 && kt[0] !== '0') { kt.unshift(0); vs.unshift(vs[0]); }
  if (kt[kt.length - 1] < 1) { kt.push(1); vs.push(vs[vs.length - 1]); }
  return {
    keyTimes: kt.map(t => (typeof t === 'number' ? t.toFixed(5) : t)).join(';'),
    values: vs.join(';'),
  };
}

// ─────────────────────────────────────────────────────────────
//  Particle burst on impact
// ─────────────────────────────────────────────────────────────

function particleBurst(cx, cy, hitRel, endRel, totalDur) {
  const DIRS   = [[-9,-9],[9,-9],[-9,9],[9,9],[-13,0],[13,0]];
  const colors = ['#ff3344','#ffaa22','#ff5500','#ffee55','#ff3344','#ffaa22'];
  let out = '';
  const hR = parseFloat(hitRel), eR = parseFloat(endRel);
  DIRS.forEach(([dx, dy], i) => {
    const col     = colors[i];
    const fadeRel = Math.min(eR + 0.06, 0.9999);

    const xAnim = closeAnim([0, hR, eR], [`${cx}`, `${cx+dx/2}`, `${cx+dx}`]);
    const yAnim = closeAnim([0, hR, eR], [`${cy}`, `${cy+dy/2}`, `${cy+dy}`]);
    const oAnim = closeAnim([0, hR, hR, fadeRel], ['0', '0', '1', '0']);

    out += `
    <rect width="3" height="3" fill="${col}" opacity="0" rx="1">
      <animate attributeName="x" values="${xAnim.values}"
        keyTimes="${xAnim.keyTimes}" dur="${totalDur}s" repeatCount="indefinite" calcMode="linear"/>
      <animate attributeName="y" values="${yAnim.values}"
        keyTimes="${yAnim.keyTimes}" dur="${totalDur}s" repeatCount="indefinite" calcMode="linear"/>
      <animate attributeName="opacity" values="${oAnim.values}"
        keyTimes="${oAnim.keyTimes}" dur="${totalDur}s" repeatCount="indefinite" calcMode="discrete"/>
    </rect>`;
  });
  return out;
}

// ─────────────────────────────────────────────────────────────
//  Build the SVG
// ─────────────────────────────────────────────────────────────

function buildSVG(calendar) {
  const { weeks, totalContributions } = calendar;

  // ── Layout ──
  const CELL    = 11;
  const GAP     = 3;
  const STEP    = CELL + GAP;

  const SPRITE_W = 96;
  const SPRITE_H = 114;
  const GRID_X   = SPRITE_W + 14;
  const GRID_Y   = 30;

  const HAND_CX = HAND_X;            // hand x relative to sprite
  const HAND_CY = GRID_Y + HAND_Y;   // hand y in canvas coords

  const SVG_W = GRID_X + weeks.length * STEP + 20;
  const SVG_H = GRID_Y + SPRITE_H + 24;

  // ── Flat cell list ──
  const cells = [];
  weeks.forEach((week, wi) => {
    week.contributionDays.forEach((day, di) => {
      cells.push({
        id:    `c${wi}_${di}`,
        x:     GRID_X + wi * STEP,
        y:     GRID_Y + di * STEP,
        count: day.contributionCount,
        color: cellColor(day.contributionCount),
      });
    });
  });

  const active = cells.filter(c => c.count > 0);

  // ── Timing (seconds) ──
  const CHARGE      = 0.20;
  const RELEASE_HOLD= 0.04;
  const FLIGHT       = 0.24;   // slowed down slightly so the shot is clearly visible
  const RECOVER     = 0.08;
  const PAUSE       = 0.05;
  const EVENT       = CHARGE + RELEASE_HOLD + FLIGHT + RECOVER + PAUSE;
  const INTRO       = 0.5;
  const OUTRO       = 1.0;
  const TOTAL       = INTRO + active.length * EVENT + OUTRO;

  const events = active.map((cell, i) => {
    const t0          = INTRO + i * EVENT;
    const tChargeEnd  = t0 + CHARGE;
    const tRelease    = tChargeEnd + RELEASE_HOLD;
    const tImpact     = tRelease + FLIGHT;
    const tRecoverEnd = tImpact + RECOVER;
    const tEnd        = tRecoverEnd + PAUSE;
    return { cell, t0, tChargeEnd, tRelease, tImpact, tRecoverEnd, tEnd };
  });

  // ── Sprite frame visibility windows ──
  const frameWindows = Array.from({ length: 12 }, () => []);
  frameWindows[IDLE_FRAME].push({ start: 0, end: INTRO });

  events.forEach(({ t0, tChargeEnd, tRelease, tImpact, tRecoverEnd }) => {
    const stepDur = (tChargeEnd - t0) / CHARGE_FRAMES.length;
    CHARGE_FRAMES.forEach((frameIdx, si) => {
      frameWindows[frameIdx].push({ start: t0 + si * stepDur, end: t0 + (si + 1) * stepDur });
    });
    // Release pose held through release + flight
    frameWindows[RELEASE_FRAME].push({ start: tChargeEnd, end: tImpact });
    // Recoil
    frameWindows[RECOIL_FRAME].push({ start: tImpact, end: tRecoverEnd });
  });

  const outroStart = INTRO + active.length * EVENT;
  frameWindows[IDLE_FRAME].push({ start: outroStart, end: TOTAL });
  events.forEach(({ tRecoverEnd, tEnd }) => {
    frameWindows[IDLE_FRAME].push({ start: tRecoverEnd, end: tEnd });
  });

  function windowsToAnimate(windows, totalDur) {
    const evs = [];
    windows.forEach(({ start, end }) => { evs.push({ t: start, v: 1 }, { t: end, v: 0 }); });
    evs.sort((a, b) => a.t - b.t);
    const kt = ['0'], kv = ['0'];
    evs.forEach(({ t, v }) => { kt.push((t / totalDur).toFixed(5)); kv.push(String(v)); });
    kt.push('1'); kv.push('0');
    return { keyTimes: kt.join(';'), values: kv.join(';') };
  }

  let spriteLayer = '';
  SPRITE_FRAMES.forEach((dataUri, i) => {
    if (frameWindows[i].length === 0) return;
    const { keyTimes, values } = windowsToAnimate(frameWindows[i], TOTAL);
    spriteLayer += `
  <image href="${dataUri}"
    x="0" y="${GRID_Y}" width="${SPRITE_W}" height="${SPRITE_H}"
    image-rendering="pixelated" opacity="0">
    <animate attributeName="opacity"
      values="${values}" keyTimes="${keyTimes}"
      dur="${TOTAL}s" repeatCount="indefinite" calcMode="discrete"/>
  </image>`;
  });

  // ── Fireball projectiles + destruction + particles + labels ──
  const ATTACKS = ['CURSED ENERGY!', 'BLACK FLASH!', 'DIVERGENT FIST!', 'BOOST!', 'BREAKDOWN!'];

  let fireballLayer  = '';
  let muzzleLayer    = '';
  let destroyLayer   = '';
  let particleLayer  = '';
  let labelLayer     = '';

  events.forEach(({ cell, tRelease, tImpact, tRecoverEnd }, idx) => {
    const cx = cell.x + CELL / 2;
    const cy = cell.y + CELL / 2;

    const dx = cx - HAND_CX;
    const dy = cy - HAND_CY;
    const angle = (Math.atan2(dy, dx) * 180 / Math.PI).toFixed(2);

    const relReleaseStart = Math.max(0, (tRelease / TOTAL) - 0.0008);
    const relRelease      = tRelease / TOTAL;
    const relImpact        = tImpact / TOTAL;
    const relImpactEnd    = Math.min(relImpact + 0.0008, 0.99999);

    // ── Opacity: visible only during the flight window ──
    const opAnim = closeAnim(
      [0, relReleaseStart, relRelease, relImpact, relImpactEnd],
      ['0', '0', '1', '1', '0']
    );

    // ── Position: animateTransform translate, hand -> target.
    //    MUST close at keyTime=1 or browsers silently drop it. ──
    const handPos   = `${HAND_CX.toFixed(1)} ${HAND_CY.toFixed(1)}`;
    const targetPos = `${cx.toFixed(1)} ${cy.toFixed(1)}`;
    const posAnim = closeAnim(
      [0, relRelease, relImpact],
      [handPos, handPos, targetPos]
    );

    // Fireball: outer <g> animates translate (position+opacity),
    // inner <g> has a STATIC rotate so movement and orientation
    // never fight each other. Filter is applied to the leaf image
    // (local, stable bbox) — NOT to a giant outer group, which is
    // what was clipping every fireball out of view before.
    fireballLayer += `
  <g opacity="0">
    <animate attributeName="opacity" values="${opAnim.values}" keyTimes="${opAnim.keyTimes}"
      dur="${TOTAL}s" repeatCount="indefinite" calcMode="discrete"/>
    <animateTransform attributeName="transform" type="translate"
      values="${posAnim.values}" keyTimes="${posAnim.keyTimes}"
      dur="${TOTAL}s" repeatCount="indefinite" calcMode="linear"/>
    <g transform="rotate(${angle})">
      <image href="${FIREBALL_SPRITE}" x="${-FB_W/2}" y="${-FB_H/2}" width="${FB_W}" height="${FB_H}"
        image-rendering="pixelated" filter="url(#glow)"/>
    </g>
  </g>`;

    // ── Muzzle flash at the hand, exactly when the shot fires ──
    const muzAnim = closeAnim(
      [0, relReleaseStart, relRelease, Math.min(relRelease + 0.0015, 0.99999)],
      ['0', '0', '1', '0']
    );
    muzzleLayer += `
  <circle cx="${HAND_CX.toFixed(1)}" cy="${HAND_CY.toFixed(1)}" r="9" fill="#ffcc55" opacity="0" filter="url(#glow)">
    <animate attributeName="opacity" values="${muzAnim.values}" keyTimes="${muzAnim.keyTimes}"
      dur="${TOTAL}s" repeatCount="indefinite" calcMode="discrete"/>
  </circle>`;

    // ── Destruction flash + permanent erase ──
    const hitRel  = relImpact;
    const endRel  = tRecoverEnd / TOTAL;
    const doneRel = Math.min((tRecoverEnd + 0.5) / TOTAL, 0.9999);

    const fillAnim = closeAnim(
      [0, hitRel, hitRel, endRel, doneRel],
      [cell.color, cell.color, '#ff6b35', '#ff1100', '#0d1117']
    );
    const flashOpAnim = closeAnim([0, hitRel, hitRel], ['0', '0', '1']);
    const eraseOpAnim = closeAnim([0, doneRel, doneRel], ['0', '0', '1']);

    destroyLayer += `
  <rect x="${cell.x}" y="${cell.y}" width="${CELL}" height="${CELL}" rx="2" opacity="0">
    <animate attributeName="fill" values="${fillAnim.values}" keyTimes="${fillAnim.keyTimes}"
      dur="${TOTAL}s" repeatCount="indefinite" calcMode="discrete"/>
    <animate attributeName="opacity" values="${flashOpAnim.values}" keyTimes="${flashOpAnim.keyTimes}"
      dur="${TOTAL}s" repeatCount="indefinite" calcMode="discrete"/>
  </rect>
  <rect x="${cell.x}" y="${cell.y}" width="${CELL}" height="${CELL}" rx="2" fill="#0d1117" opacity="0">
    <animate attributeName="opacity" values="${eraseOpAnim.values}" keyTimes="${eraseOpAnim.keyTimes}"
      dur="${TOTAL}s" repeatCount="indefinite" calcMode="discrete"/>
  </rect>`;

    particleLayer += particleBurst(cx, cy, hitRel.toFixed(5), endRel.toFixed(5), TOTAL);

    if (idx % 5 === 0) {
      const label   = ATTACKS[Math.floor(idx / 5) % ATTACKS.length];
      const fadeRel = Math.min((tRecoverEnd + 0.12) / TOTAL, 0.9999);

      const lblOpAnim = closeAnim([0, hitRel, hitRel, endRel, fadeRel], ['0', '0', '1', '1', '0']);
      const lblYAnim  = closeAnim([0, hitRel, endRel, fadeRel], [`${cy}`, `${cy}`, `${cy-6}`, `${cy-10}`]);

      labelLayer += `
  <text x="${cx}" y="${cy - 8}" text-anchor="middle"
    font-family="monospace" font-size="7" font-weight="bold" fill="#ff8844" opacity="0">
    ${label}
    <animate attributeName="opacity" values="${lblOpAnim.values}" keyTimes="${lblOpAnim.keyTimes}"
      dur="${TOTAL}s" repeatCount="indefinite" calcMode="discrete"/>
    <animate attributeName="y" values="${lblYAnim.values}" keyTimes="${lblYAnim.keyTimes}"
      dur="${TOTAL}s" repeatCount="indefinite" calcMode="linear"/>
  </text>`;
    }
  });

  return `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink"
  width="${SVG_W}" height="${SVG_H}" viewBox="0 0 ${SVG_W} ${SVG_H}"
  role="img" aria-label="Yuji Itadori destroying GitHub contributions with cursed energy">

  <defs>
    <filter id="glow" x="-80%" y="-80%" width="260%" height="260%">
      <feGaussianBlur in="SourceGraphic" stdDeviation="3" result="b"/>
      <feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge>
    </filter>
  </defs>

  <rect width="${SVG_W}" height="${SVG_H}" rx="8" fill="#0d1117"/>

  <text x="${SVG_W / 2}" y="20" fill="#ff8844"
    font-size="11" font-family="'Courier New',monospace"
    font-weight="bold" text-anchor="middle" letter-spacing="1">
    \U0001F525  ${totalContributions} contributions — CURSED ENERGY BLAST!  \U0001F4A5
  </text>

  <!-- Base grid -->
  ${cells.map(c =>
    `<rect id="${c.id}" x="${c.x}" y="${c.y}" width="${CELL}" height="${CELL}" rx="2" fill="${c.color}"/>`
  ).join('\n  ')}

  <!-- Destruction layers -->
  ${destroyLayer}

  <!-- Particles -->
  ${particleLayer}

  <!-- Attack labels -->
  ${labelLayer}

  <!-- Muzzle flashes at the hand -->
  ${muzzleLayer}

  <!-- Flying fireballs (filter applied per-image, not on the whole batch) -->
  ${fireballLayer}

  <!-- Yuji sprite (frame-cycled) -->
  ${spriteLayer}

  <text x="${SVG_W - 12}" y="${SVG_H - 6}" fill="#333" font-size="8"
    font-family="monospace" text-anchor="end">yuji-contribution-anim</text>
</svg>`;
}

// ─────────────────────────────────────────────────────────────
//  Entry point
// ─────────────────────────────────────────────────────────────

async function main() {
  if (!TOKEN) throw new Error('❌  GITHUB_TOKEN env variable not set');
  if (!USER)  throw new Error('❌  GITHUB_USERNAME env variable not set');

  console.log(`🔥  Fetching contributions for @${USER}…`);
  const calendar = await fetchContributions(USER);
  const activeCount = calendar.weeks
    .flatMap(w => w.contributionDays)
    .filter(d => d.contributionCount > 0).length;
  console.log(`✅  ${calendar.totalContributions} total (${activeCount} active days)`);

  const svg  = buildSVG(calendar);
  const path = 'yuji-animation.svg';
  fs.writeFileSync(path, svg, 'utf-8');
  console.log(`💥  Saved ${path}  (${(svg.length / 1024).toFixed(1)} KB)`);
}

main().catch(err => { console.error('❌', err.message); process.exit(1); });
